### Implementation Steps

**Phase 1: Tenant-Aware Instrumentation (Weeks 1-2)**

**Step 1.1: Implement Tenant Context Middleware**

```csharp
// TenantContextMiddleware.cs
public class TenantContextMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<TenantContextMiddleware> _logger;

    public async Task InvokeAsync(HttpContext context)
    {
        // Extract tenant ID from request (header, JWT claim, subdomain)
        var tenantId = ExtractTenantId(context.Request);

        if (string.IsNullOrEmpty(tenantId))
        {
            _logger.LogWarning("Request missing tenant ID: {Path}",
                context.Request.Path);
            context.Response.StatusCode = 400;
            await context.Response.WriteAsync("Missing tenant identification");
            return;
        }

        // Store tenant context for current request
        TenantContext.Current = new TenantContext
        {
            TenantId = tenantId,
            RequestId = Guid.NewGuid().ToString(),
            Timestamp = DateTime.UtcNow
        };

        // Add tenant ID to logging context for all subsequent logs
        using (_logger.BeginScope(new Dictionary<string, object>
        {
            ["tenant_id"] = tenantId,
            ["request_id"] = TenantContext.Current.RequestId
        }))
        {
            await _next(context);
        }
    }

    private string ExtractTenantId(HttpRequest request)
    {
        // Tenant identification strategies defined in Architecture Core Pattern (PTN-APP-MTN-002)

        // Option 1: From custom header
        if (request.Headers.TryGetValue("X-Tenant-ID", out var headerValue))
            return headerValue.ToString();

        // Option 2: From JWT claim
        var jwtToken = request.Headers["Authorization"]
            .ToString().Replace("Bearer ", "");
        if (!string.IsNullOrEmpty(jwtToken))
        {
            var tenantClaim = ParseJwt(jwtToken)?.FindFirst("tenant_id");
            if (tenantClaim != null)
                return tenantClaim.Value;
        }

        // Option 3: From subdomain (e.g., acme.platform.com)
        var host = request.Host.Host;
        if (host.Contains("."))
            return host.Split('.')[0];

        return null;
    }
}

// TenantContext.cs
public class TenantContext
{
    private static AsyncLocal<TenantContext> _current = new AsyncLocal<TenantContext>();

    public static TenantContext Current
    {
        get => _current.Value;
        set => _current.Value = value;
    }

    public string TenantId { get; set; }
    public string RequestId { get; set; }
    public DateTime Timestamp { get; set; }
}
```

**Step 1.2: Configure Structured Logging with Tenant Context**

```csharp
// Program.cs - Serilog configuration
Log.Logger = new LoggerConfiguration()
    .Enrich.FromLogContext() // Enables enrichment from BeginScope
    .Enrich.With(new TenantEnricher()) // Custom enricher for tenant context
    .WriteTo.Console(
        outputTemplate: "[{Timestamp:HH:mm:ss} {Level:u3}] " +
                       "[Tenant: {tenant_id}] [Request: {request_id}] " +
                       "{Message:lj}{NewLine}{Exception}")
    .WriteTo.Elasticsearch(new ElasticsearchSinkOptions(
        new Uri("https://elasticsearch:9200"))
    {
        AutoRegisterTemplate = true,
        IndexFormat = "app-logs-{0:yyyy.MM}",
        ModifyConnectionSettings = conn => conn.BasicAuthentication("user", "pass")
    })
    .CreateLogger();

// TenantEnricher.cs
public class TenantEnricher : ILogEventEnricher
{
    public void Enrich(LogEvent logEvent, ILogEventPropertyFactory factory)
    {
        var context = TenantContext.Current;
        if (context != null)
        {
            logEvent.AddPropertyIfAbsent(factory.CreateProperty(
                "tenant_id", context.TenantId));
            logEvent.AddPropertyIfAbsent(factory.CreateProperty(
                "request_id", context.RequestId));
        }
    }
}
```

**Step 1.3: Implement Tenant-Tagged Metrics**

```csharp
// MetricsService.cs
public class MetricsService
{
    private readonly IMetricsRoot _metrics;

    public MetricsService(IMetricsRoot metrics)
    {
        _metrics = metrics;
    }

    public void RecordApiRequest(string endpoint, int statusCode, double durationMs)
    {
        var tenantId = TenantContext.Current?.TenantId ?? "unknown";

        // Counter: API requests by tenant, endpoint, status
        _metrics.Measure.Counter.Increment(
            new CounterOptions
            {
                Name = "api_requests_total",
                Tags = new MetricTags(
                    new[] { "tenant_id", "endpoint", "status_code" },
                    new[] { tenantId, endpoint, statusCode.ToString() })
            });

        // Histogram: API response time distribution
        _metrics.Measure.Histogram.Update(
            new HistogramOptions
            {
                Name = "api_request_duration_ms",
                Tags = new MetricTags(
                    new[] { "tenant_id", "endpoint" },
                    new[] { tenantId, endpoint })
            },
            durationMs);
    }

    public void RecordDatabaseQuery(string operation, double durationMs)
    {
        var tenantId = TenantContext.Current?.TenantId ?? "unknown";

        _metrics.Measure.Histogram.Update(
            new HistogramOptions
            {
                Name = "database_query_duration_ms",
                Tags = new MetricTags(
                    new[] { "tenant_id", "operation" },
                    new[] { tenantId, operation })
            },
            durationMs);
    }

    public void RecordResourceUsage(string resourceType, double value)
    {
        var tenantId = TenantContext.Current?.TenantId ?? "unknown";

        _metrics.Measure.Gauge.SetValue(
            new GaugeOptions
            {
                Name = $"resource_usage_{resourceType}",
                Tags = new MetricTags("tenant_id", tenantId)
            },
            value);
    }
}

// Usage in application code
public class ClaimsController : ControllerBase
{
    private readonly IClaimsService _claimsService;
    private readonly MetricsService _metrics;

    [HttpPost("claims")]
    public async Task<IActionResult> SubmitClaim(ClaimRequest request)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            var result = await _claimsService.ProcessClaimAsync(request);
            stopwatch.Stop();

            _metrics.RecordApiRequest("/claims", 200, stopwatch.ElapsedMilliseconds);

            return Ok(result);
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            _metrics.RecordApiRequest("/claims", 500, stopwatch.ElapsedMilliseconds);
            throw;
        }
    }
}
```

**Phase 2: Tenant-Scoped Log and Trace Collection (Weeks 3-4)**

**Step 2.1: Configure Distributed Tracing with Tenant Context**

```csharp
// Startup.cs - OpenTelemetry configuration
services.AddOpenTelemetryTracing(builder =>
{
    builder
        .AddAspNetCoreInstrumentation(options =>
        {
            // Add tenant_id as span attribute
            options.Enrich = (activity, eventName, rawObject) =>
            {
                var tenantId = TenantContext.Current?.TenantId;
                if (!string.IsNullOrEmpty(tenantId))
                {
                    activity.SetTag("tenant_id", tenantId);
                    activity.SetTag("request_id", TenantContext.Current.RequestId);
                }
            };
        })
        .AddHttpClientInstrumentation()
        .AddSqlClientInstrumentation(options =>
        {
            options.SetDbStatementForText = true;
            options.RecordException = true;
            options.Enrich = (activity, eventName, rawObject) =>
            {
                // Add tenant context to database spans
                var tenantId = TenantContext.Current?.TenantId;
                if (!string.IsNullOrEmpty(tenantId))
                {
                    activity.SetTag("tenant_id", tenantId);
                }
            };
        })
        .AddJaegerExporter(options =>
        {
            options.AgentHost = "jaeger";
            options.AgentPort = 6831;
        });
});
```

**Step 2.2: Implement Elasticsearch Log Queries with Tenant Filtering**

```csharp
// LogQueryService.cs
public class LogQueryService
{
    private readonly IElasticClient _elasticClient;
    private readonly ITenantAuthorizationService _authService;

    public async Task<List<LogEntry>> QueryLogsAsync(
        string userId,
        string tenantId,
        LogQueryRequest request)
    {
        // Verify user authorized for tenant
        if (!await _authService.IsAuthorizedForTenantAsync(userId, tenantId))
        {
            throw new UnauthorizedAccessException(
                $"User {userId} not authorized for tenant {tenantId}");
        }

        var searchRequest = new SearchRequest<LogEntry>("app-logs-*")
        {
            Query = new BoolQuery
            {
                Must = new QueryContainer[]
                {
                    // Always filter by tenant_id
                    new TermQuery
                    {
                        Field = "tenant_id",
                        Value = tenantId
                    },
                    // Time range filter
                    new DateRangeQuery
                    {
                        Field = "timestamp",
                        GreaterThanOrEqualTo = request.StartTime,
                        LessThanOrEqualTo = request.EndTime
                    }
                },
                Filter = BuildAdditionalFilters(request)
            },
            Sort = new List<ISort>
            {
                new FieldSort { Field = "timestamp", Order = SortOrder.Descending }
            },
            Size = request.Limit ?? 100
        };

        var response = await _elasticClient.SearchAsync<LogEntry>(searchRequest);

        return response.Documents.ToList();
    }

    private List<QueryContainer> BuildAdditionalFilters(LogQueryRequest request)
    {
        var filters = new List<QueryContainer>();

        if (!string.IsNullOrEmpty(request.LogLevel))
        {
            filters.Add(new TermQuery
            {
                Field = "level",
                Value = request.LogLevel
            });
        }

        if (!string.IsNullOrEmpty(request.SearchText))
        {
            filters.Add(new MatchQuery
            {
                Field = "message",
                Query = request.SearchText
            });
        }

        return filters;
    }
}
```

**Phase 3: Tenant-Specific Alerting (Weeks 5-6)**

**Step 3.1: Implement Dynamic Alert Thresholds per Tenant**

```csharp
// TenantAlertConfigurationService.cs
public class TenantAlertConfigurationService
{
    private readonly DbContext _context;
    private readonly IAlertManager _alertManager;

    public async Task ConfigureDefaultAlertsForTenantAsync(string tenantId)
    {
        var tenant = await _context.Tenants.FindAsync(tenantId);

        // Create tenant-specific alert rules with dynamic thresholds
        var alertRules = new[]
        {
            new AlertRule
            {
                TenantId = tenantId,
                Name = $"High API Response Time - {tenant.Name}",
                Query = $"avg_over_time(api_request_duration_ms{{tenant_id=\"{tenantId}\"}}[5m])",
                Threshold = GetResponseTimeThreshold(tenant.Tier), // Different by tier
                Severity = "warning",
                NotificationChannels = GetNotificationChannels(tenant.Tier)
            },
            new AlertRule
            {
                TenantId = tenantId,
                Name = $"High Error Rate - {tenant.Name}",
                Query = $"rate(api_requests_total{{tenant_id=\"{tenantId}\",status_code=~\"5..\"}}" +
                        $"[5m]) / rate(api_requests_total{{tenant_id=\"{tenantId}\"}}[5m]) * 100",
                Threshold = 5.0, // 5% error rate
                Severity = "critical",
                NotificationChannels = GetNotificationChannels(tenant.Tier)
            },
            new AlertRule
            {
                TenantId = tenantId,
                Name = $"Storage Approaching Limit - {tenant.Name}",
                Query = $"resource_usage_storage_gb{{tenant_id=\"{tenantId}\"}}",
                Threshold = tenant.StorageLimitGB * 0.8, // 80% of limit
                Severity = "warning",
                NotificationChannels = new[] { "customer-email", "support-team" }
            }
        };

        foreach (var rule in alertRules)
        {
            await _alertManager.CreateAlertRuleAsync(rule);
        }
    }

    private double GetResponseTimeThreshold(string tier)
    {
        return tier switch
        {
            "enterprise" => 500, // 500ms threshold for enterprise
            "standard" => 1000,  // 1000ms for standard
            "trial" => 2000,     // 2000ms for trial
            _ => 1000
        };
    }

    private string[] GetNotificationChannels(string tier)
    {
        return tier switch
        {
            "enterprise" => new[] { "pagerduty", "slack", "email", "customer-webhook" },
            "standard" => new[] { "email", "customer-email" },
            "trial" => new[] { "email" },
            _ => new[] { "email" }
        };
    }
}
```

**Step 3.2: Configure Prometheus Alert Rules**

```yaml
# prometheus-tenant-alerts.yml
groups:

  - name: tenant_performance
    interval: 30s
    rules:
      # Alert on high response time per tenant
      - alert: TenantHighResponseTime
        expr: |
          (
            histogram_quantile(0.95,
              rate(api_request_duration_ms_bucket{tenant_id!=""}[5m])
            ) > 2000
          )
        for: 5m
        labels:
          severity: warning
        annotations:
          summary: "High API response time for tenant {{ $labels.tenant_id }}"
          description: "95th percentile response time is {{ $value }}ms for tenant {{ $labels.tenant_id }}"

      # Alert on elevated error rate per tenant
      - alert: TenantHighErrorRate
        expr: |
          (
            sum by (tenant_id) (rate(api_requests_total{status_code=~"5.."}[5m]))
            /
            sum by (tenant_id) (rate(api_requests_total[5m]))
          ) * 100 > 5
        for: 10m
        labels:
          severity: critical
        annotations:
          summary: "High error rate for tenant {{ $labels.tenant_id }}"
          description: "Error rate is {{ $value | humanizePercentage }} for tenant {{ $labels.tenant_id }}"

      # Alert on storage threshold per tenant
      - alert: TenantStorageApproachingLimit
        expr: |
          (
            resource_usage_storage_gb{tenant_id!=""}
            /
            resource_limit_storage_gb{tenant_id!=""}
          ) > 0.8
        for: 1h
        labels:
          severity: warning
        annotations:
          summary: "Storage approaching limit for tenant {{ $labels.tenant_id }}"
          description: "Storage usage is {{ $value | humanizePercentage }} of limit for tenant {{ $labels.tenant_id }}"
```

**Phase 4: Customer-Facing Dashboards (Weeks 7-8)**

**Step 4.1: Build Customer Self-Service Dashboard API**

```csharp
// CustomerDashboardController.cs
[ApiController]
[Route("api/dashboard")]
[Authorize] // Requires authenticated tenant user
public class CustomerDashboardController : ControllerBase
{
    private readonly IMetricsQueryService _metricsService;
    private readonly ITenantAuthorizationService _authService;

    [HttpGet("usage")]
    public async Task<ActionResult<UsageDashboardData>> GetUsageDashboard(
        [FromQuery] DateTime startDate,
        [FromQuery] DateTime endDate)
    {
        var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        var tenantId = User.FindFirst("tenant_id")?.Value;

        // Verify authorization
        if (!await _authService.IsAuthorizedForTenantAsync(userId, tenantId))
            return Forbid();

        // Query tenant-scoped metrics
        var dashboard = new UsageDashboardData
        {
            TenantId = tenantId,
            Period = new { StartDate = startDate, EndDate = endDate },
            ApiCallsTotal = await _metricsService.GetApiCallCountAsync(
                tenantId, startDate, endDate),
            ApiCallsByEndpoint = await _metricsService.GetApiCallsByEndpointAsync(
                tenantId, startDate, endDate),
            AverageResponseTime = await _metricsService.GetAverageResponseTimeAsync(
                tenantId, startDate, endDate),
            ErrorRate = await _metricsService.GetErrorRateAsync(
                tenantId, startDate, endDate),
            StorageUsageGB = await _metricsService.GetCurrentStorageUsageAsync(tenantId),
            StorageLimitGB = await _metricsService.GetStorageLimitAsync(tenantId),
            ActiveUsers = await _metricsService.GetActiveUserCountAsync(
                tenantId, startDate, endDate),
            DataProcessedGB = await _metricsService.GetDataProcessedAsync(
                tenantId, startDate, endDate)
        };

        return Ok(dashboard);
    }

    [HttpGet("performance")]
    public async Task<ActionResult<PerformanceDashboardData>> GetPerformanceDashboard(
        [FromQuery] string timeRange = "24h")
    {
        var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        var tenantId = User.FindFirst("tenant_id")?.Value;

        if (!await _authService.IsAuthorizedForTenantAsync(userId, tenantId))
            return Forbid();

        var endTime = DateTime.UtcNow;
        var startTime = timeRange switch
        {
            "1h" => endTime.AddHours(-1),
            "24h" => endTime.AddHours(-24),
            "7d" => endTime.AddDays(-7),
            "30d" => endTime.AddDays(-30),
            _ => endTime.AddHours(-24)
        };

        var dashboard = new PerformanceDashboardData
        {
            ResponseTimeSeries = await _metricsService.GetResponseTimeSeriesAsync(
                tenantId, startTime, endTime),
            ResponseTimePercentiles = await _metricsService.GetResponseTimePercentilesAsync(
                tenantId, startTime, endTime),
            Availability = await _metricsService.GetAvailabilityAsync(
                tenantId, startTime, endTime),
            SlaCompliance = await _metricsService.GetSlaComplianceAsync(
                tenantId, startTime, endTime)
        };

        return Ok(dashboard);
    }
}
```

