### Code Examples

**Example 1: Tenant Performance Troubleshooting**

```csharp
// Support engineer investigates slow performance for specific tenant
var tenantId = "acme-health-plan";

// Query tenant-specific metrics
var metrics = await monitoringService.GetTenantMetricsAsync(tenantId,
    startTime: DateTime.UtcNow.AddHours(-4),
    endTime: DateTime.UtcNow);

Console.WriteLine($"Average Response Time: {metrics.AverageResponseTime}ms");
Console.WriteLine($"95th Percentile: {metrics.P95ResponseTime}ms");
Console.WriteLine($"Error Rate: {metrics.ErrorRate}%");

// Query tenant-scoped logs for errors
var errorLogs = await logService.QueryLogsAsync(tenantId, new LogQuery
{
    LogLevel = "Error",
    StartTime = DateTime.UtcNow.AddHours(-1),
    Limit = 50
});

foreach (var log in errorLogs)
{
    Console.WriteLine($"[{log.Timestamp}] {log.Message}");
}

// Get distributed trace for slow request
var slowTraces = await traceService.GetSlowTracesAsync(tenantId,
    thresholdMs: 2000,
    limit: 10);

foreach (var trace in slowTraces)
{
    Console.WriteLine($"\nTrace ID: {trace.TraceId}");
    Console.WriteLine($"Total Duration: {trace.TotalDuration}ms");
    foreach (var span in trace.Spans.OrderBy(s => s.StartTime))
    {
        Console.WriteLine($"  - {span.ServiceName}.{span.OperationName}: {span.Duration}ms");
    }
}
```

